import React, { useContext } from 'react';
import { Routes, Route, Navigate } from 'react-router-dom';
import { AuthContext } from './context/AuthContext';
import Login from './components/Auth/Login';
import Signup from './components/Auth/Signup';
import ProjectList from './components/Project/ProjectList';
import ProjectForm from './components/Project/ProjectForm';
import TaskList from './components/Task/TaskList';

function App() {
  const { user } = useContext(AuthContext);

  return (
    <div className="min-h-screen bg-gray-100">
      <Routes>
        <Route
          path="/login"
          element={user ? <Navigate to="/projects" /> : <Login />}
        />
        <Route
          path="/signup"
          element={user ? <Navigate to="/projects" /> : <Signup />}
        />
        <Route
          path="/projects"
          element={user ? <ProjectList /> : <Navigate to="/login" />}
        />
        <Route
          path="/projects/new"
          element={user ? <ProjectForm /> : <Navigate to="/login" />}
        />
        <Route
          path="/projects/:projectId"
          element={user ? <TaskList /> : <Navigate to="/login" />}
        />
        <Route path="/" element={<Navigate to="/projects" />} />
      </Routes>
    </div>
  );
}

export default App;
